simStudyBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "simStudyBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "studysim",
                name = "simStudy",
                version = c(0,4,0),
                options = options,
                results = simStudyResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Simulated study
#'
#' Simulates a plausible medical study for teaching: a clinical scenario from 
#' the library, a study design compatible with its outcome, a sample size and 
#' some realism. The dataset opens in a new window; the answer key holds the 
#' true parameters and what the design is expected to estimate.
#' 
#'
#' @examples
#' \donttest{
#' # in R, use the engine directly:
#' # sc <- studysim:::load_scenario(studysim:::builtin_library(), "chd_incidence")
#' # studysim:::simulate_study(sc, "chd", "cohort", n = 1000)
#'}
#' @param data .
#' @param libName name of the custom library file read by the Browse button
#'   (display only)
#' @param libContent base64 of the custom library file (JSON, YAML, Excel or
#'   zip)
#' @param designFilter shows in the pickers only the scenarios (and outcomes)
#'   that fit this design
#' @param scenario scenario id
#' @param outcome outcome id; empty means the scenario's first outcome
#' @param design study design; must fit the outcome
#' @param secondary adds the scenario's other outcomes as columns, for the
#'   same people (cross-sectional, cohort, prognosis and trial designs)
#' @param measured one entry per scenario variable, list(var = name, include =
#'   TRUE/FALSE, exposure = TRUE/FALSE (the variable the biases act on), form =
#'   "continuous"/"median"/"tertiles"/"quartiles"/"quintiles"/"cuts"/"log2"/"log10"/"scale",
#'   cuts = "18.5, 25, 30" or "10\%, 90\%", or the divisor for scale, e.g.
#'   "10"); included variables are in the dataset, the others are unmeasured
#'   (they still act); form groups a continuous variable (quantiles from the
#'   sample)
#' @param n number of participants (cases plus controls in case-control
#'   designs)
#' @param ccRatio case-control designs, controls per case (1 to 10); empty:
#'   the scenario's value
#' @param followup in the outcome's time units; empty: the scenario's value
#' @param loss empty: the scenario's value (2\% by default)
#' @param accrual staggered entry over this time; empty: the design's value
#'   (prognosis 2)
#' @param subcohort case-cohort design, the random subcohort as a percentage
#'   of the cohort; empty: the scenario's value (10\%)
#' @param looks randomised trial, number of equally spaced analyses (2 to 5; 0
#'   or 1 = none); adds a look column
#' @param clusters cluster randomised trial, number of clusters (4 to 1000);
#'   empty: the scenario's value (20)
#' @param icc cluster randomised trial (0 to 0.9); empty: the scenario's value
#'   (0.05)
#' @param interaction 2x2 factorial trial, added to the linear predictor of
#'   those given both (beta, or log OR/HR/RR); empty: the scenario's value (0)
#' @param visits longitudinal trial, visits after baseline (1 to 12); empty:
#'   the scenario's value (4)
#' @param dropout longitudinal trial, participants missing the last visit
#'   (missing at random); empty: the scenario's value (20\%)
#' @param regions ecological study, number of regions (3 to 500); empty: the
#'   scenario's value (30)
#' @param regionSize ecological study (10 to 100000); empty: the scenario's
#'   value (2000)
#' @param regionSd ecological study, SD of the regions' shifts of the
#'   variables (latent scale, 0 to 3); empty: the scenario's value (0.5)
#' @param contextSd ecological study, SD of an unexplained region effect on
#'   the outcome (0 to 3); empty: the scenario's value (0.2)
#' @param threshold before-after study, enrol only people above this
#'   percentile of the value before (0 to 95); empty: the scenario's value (0 =
#'   everybody)
#' @param mcBias method comparison, constant difference B - A in the outcome's
#'   units; empty: the scenario's value
#' @param mcSlope method comparison, B per unit of the true value (0.2 to 5);
#'   empty: the scenario's value
#' @param mcErrorA method comparison, random error of A (0 to 100); empty: the
#'   scenario's value
#' @param mcErrorB method comparison, random error of B (0 to 100); empty: the
#'   scenario's value
#' @param period crossover trial, change in the second period; empty: the
#'   scenario's value
#' @param carryover crossover trial, effect left by the first treatment;
#'   empty: the scenario's value
#' @param layout crossover and longitudinal trials: long (one row per period
#'   or visit, for mixed models) or wide (one row per person, for a paired
#'   t-test or repeated-measures ANOVA)
#' @param spectrum diagnostic study, the diseased in the study come from this
#'   most severe share (100 = all): spectrum bias
#' @param verification diagnostic study, share of the people negative on the
#'   first marker who get the reference standard (the others have no disease
#'   status): partial verification
#' @param recall case-control designs: this share of the unexposed cases
#'   report the exposure (a numeric exposure: cases report it this much higher,
#'   in \%)
#' @param ctrlSelect case-control designs: odds of being selected as a control
#'   if exposed (per SD of a numeric exposure), as with hospital controls; 1 =
#'   no selection bias
#' @param collider cross-sectional, cohort and case-control designs: adds
#'   \code{admitted}, caused by the outcome and by the exposure (a collider:
#'   adjusting for it biases)
#' @param nonadherence randomised trial: this share of the treated stop the
#'   treatment, more often those with a worse prognosis; adds the column
#'   \code{received}
#' @param informative followed designs: the hazard of loss to follow-up
#'   multiplies by this per SD of a person's proneness to the event (1 =
#'   non-informative)
#' @param immortal cohort and prognosis designs with an event outcome: adds
#'   \code{treated} (ever) and \code{treatment_start}; the treatment has no
#'   effect
#' @param missing .
#' @param missingMech .
#' @param reliability share of the observed variance that is true variance (1
#'   = no measurement error)
#' @param misclass .
#' @param entryErrors share of numeric cells with a typing error (decimal
#'   slip, swapped digits, 999)
#' @param lodHandling assays with a limit of detection in the library (lod)
#' @param batches .
#' @param batchCv .
#' @param batchConfounded .
#' @param noiseVars .
#' @param seed .
#' @param studentKey any text (e.g. a student ID); each key gives a different
#'   dataset (capitals and surrounding spaces are ignored)
#' @param classKeys the keys of a class (e.g. student IDs) separated by
#'   commas, semicolons or new lines; Export class writes one dataset per key
#' @param showDictionary .
#' @param showDescriptives .
#' @param showDag .
#' @param dagValues .
#' @param showKey .
#' @param openData .
#' @param exportCsv .
#' @param exportCodebook saves the data dictionary (name, description, type,
#'   values, missing) as a CSV file
#' @param exportClass a zip with one CSV and one codebook per student key, a
#'   register of keys and seeds and one answer key report, so students get only
#'   their data
#' @param exportKey saves the answer key (true model, expected estimates,
#'   diagram, notes) as an HTML page for the teacher
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$notice} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dictionary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptives} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dag} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$keyEffects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyExpected} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyTrial} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyMarkers} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyAccuracy} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyNotes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$openState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$csvState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$codebookState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$classState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyState} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$dictionary$asDF}
#'
#' \code{as.data.frame(results$dictionary)}
#'
#' @export
simStudy <- function(
    data,
    libName = "",
    libContent = "",
    designFilter = "any",
    scenario = "breast_cancer_risk",
    outcome = "",
    design = "case_control",
    secondary = FALSE,
    measured = list(),
    n = 500,
    ccRatio = "",
    followup = "",
    loss = "",
    accrual = "",
    subcohort = "",
    looks = 0,
    clusters = "",
    icc = "",
    interaction = "",
    visits = "",
    dropout = "",
    regions = "",
    regionSize = "",
    regionSd = "",
    contextSd = "",
    threshold = "",
    mcBias = "",
    mcSlope = "",
    mcErrorA = "",
    mcErrorB = "",
    period = "",
    carryover = "",
    layout = "long",
    spectrum = 100,
    verification = 100,
    recall = 0,
    ctrlSelect = 1,
    collider = FALSE,
    nonadherence = 0,
    informative = 1,
    immortal = FALSE,
    missing = 0,
    missingMech = "mcar",
    reliability = 1,
    misclass = 0,
    entryErrors = 0,
    lodHandling = "missing",
    batches = 0,
    batchCv = 15,
    batchConfounded = FALSE,
    noiseVars = 0,
    seed = 1,
    studentKey = "",
    classKeys = "",
    showDictionary = TRUE,
    showDescriptives = TRUE,
    showDag = TRUE,
    dagValues = FALSE,
    showKey = FALSE,
    openData = FALSE,
    exportCsv = FALSE,
    exportCodebook = FALSE,
    exportClass = FALSE,
    exportKey = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("simStudy requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- simStudyOptions$new(
        libName = libName,
        libContent = libContent,
        designFilter = designFilter,
        scenario = scenario,
        outcome = outcome,
        design = design,
        secondary = secondary,
        measured = measured,
        n = n,
        ccRatio = ccRatio,
        followup = followup,
        loss = loss,
        accrual = accrual,
        subcohort = subcohort,
        looks = looks,
        clusters = clusters,
        icc = icc,
        interaction = interaction,
        visits = visits,
        dropout = dropout,
        regions = regions,
        regionSize = regionSize,
        regionSd = regionSd,
        contextSd = contextSd,
        threshold = threshold,
        mcBias = mcBias,
        mcSlope = mcSlope,
        mcErrorA = mcErrorA,
        mcErrorB = mcErrorB,
        period = period,
        carryover = carryover,
        layout = layout,
        spectrum = spectrum,
        verification = verification,
        recall = recall,
        ctrlSelect = ctrlSelect,
        collider = collider,
        nonadherence = nonadherence,
        informative = informative,
        immortal = immortal,
        missing = missing,
        missingMech = missingMech,
        reliability = reliability,
        misclass = misclass,
        entryErrors = entryErrors,
        lodHandling = lodHandling,
        batches = batches,
        batchCv = batchCv,
        batchConfounded = batchConfounded,
        noiseVars = noiseVars,
        seed = seed,
        studentKey = studentKey,
        classKeys = classKeys,
        showDictionary = showDictionary,
        showDescriptives = showDescriptives,
        showDag = showDag,
        dagValues = dagValues,
        showKey = showKey,
        openData = openData,
        exportCsv = exportCsv,
        exportCodebook = exportCodebook,
        exportClass = exportClass,
        exportKey = exportKey)

    analysis <- simStudyClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

